from scipy.optimize import least_squares
t,x,v,y=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
tl=t*np.log(t)
def m1(p):
    return p[0]*tl+p[1]*x**p[2]*v**p[3]+p[4]*x**p[5]*v**p[6]
def m2(p):
    return p[0]*tl+p[1]*x**p[2]*v**p[3]+p[4]*x**p[5]*v**p[6]+p[7]
rng=np.random.default_rng(0)
for name,m,n in [('m1',m1,7),('m2',m2,8)]:
    best=(1e9,None)
    for trial in range(200):
        p0=np.array([rng.normal(), rng.normal(), rng.uniform(-3,3), rng.uniform(-3,3), rng.normal(), rng.uniform(-3,3), rng.uniform(-3,3), rng.normal()])[:n]
        try:
            s=least_squares(lambda p: m(p)-y,p0)
            nm=np.mean(s.fun**2)/np.var(y)
            if np.isfinite(nm) and nm<best[0]: best=(nm,s.x)
        except Exception:
            pass
    print(name,best[0],np.round(best[1],4))
